// Brute force: O(n^2)
for (int i = 0; i < nums.Length; i++)
    for (int j = i + 1; j < nums.Length; j++)
        if (nums[i] + nums[j] == target) return [i, j];

// Hash map: O(n)
static int[]? TwoSum(int[] nums, int target)
{
    var seen = new Dictionary<int, int>(); // wartość -> indeks
    for (int i = 0; i < nums.Length; i++)
    {
        int missing = target - nums[i];
        if (seen.TryGetValue(missing, out int j)) return [j, i];
        seen[nums[i]] = i;
    }
    return null; // brak pary – ustalone z rekruterem
}

static bool IsPalindrome(string s)
{
    int left = 0, right = s.Length - 1;
    while (left < right)
        if (s[left++] != s[right--]) return false;
    return true;
}

static int LongestUniqueSubstring(string s)
{
    var window = new HashSet<char>();
    int left = 0, best = 0;
    for (int right = 0; right < s.Length; right++)
    {
        while (window.Contains(s[right])) window.Remove(s[left++]);
        window.Add(s[right]);
        best = Math.Max(best, right - left + 1);
    }
    return best;
}

static long[] BuildPrefix(int[] nums)
{
    var prefix = new long[nums.Length + 1]; // prefix[0] = 0
    for (int i = 0; i < nums.Length; i++)
        prefix[i + 1] = prefix[i] + nums[i];
    return prefix;
}

// suma elementów nums[from..to) w O(1)
static long RangeSum(long[] prefix, int from, int to) => prefix[to] - prefix[from];

// nums = [3, 1, 4, 1, 5]  -> prefix = [0, 3, 4, 8, 9, 14]
// RangeSum(prefix, 1, 4) = 9 - 3 = 6  (1 + 4 + 1)

static int ShortestPath(char[][] grid)
{
    int rows = grid.Length, cols = grid[0].Length;
    var visited = new bool[rows, cols];
    var queue = new Queue<(int R, int C, int Dist)>();
    queue.Enqueue((0, 0, 0)); visited[0, 0] = true;
    (int, int)[] dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)];
    while (queue.Count > 0)
    {
        var (r, c, dist) = queue.Dequeue();
        if (r == rows - 1 && c == cols - 1) return dist;
        foreach (var (dr, dc) in dirs)
        {
            int nr = r + dr, nc = c + dc;
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
            if (grid[nr][nc] == '#' || visited[nr, nc]) continue;
            visited[nr, nc] = true; queue.Enqueue((nr, nc, dist + 1));
        }
    }
    return -1; // brak drogi
}

sections.text:
Po napisaniu kodu **sam zaproponuj testy** – to bardzo dobrze punktowane. Lista kontrolna przypadków brzegowych:
- pusta kolekcja / pusty string / `null`;
- jeden element;
- wszystkie elementy takie same, duplikaty;
- liczby ujemne, zero, bardzo duże wartości (**przepełnienie `int`** – dlatego w prefix sum użyliśmy `long`);
- brak rozwiązania;
- już posortowane / odwrotnie posortowane dane;
- w grafach: start = meta, start otoczony ścianami.

Przejdź kod „ręcznie” na małym przykładzie, mówiąc wartości zmiennych – to często wyłapuje błąd o jeden (**off-by-one**: `<` zamiast `<=`).

Gdy utkniesz:
1. Powiedz to: „utknąłem przy warunku końca, rozważam dwie opcje…”.
2. Wróć do przykładu i przejdź go ręcznie.
3. Przejrzyj wzorce: czy pomoże słownik? sortowanie? dwa wskaźniki? okno? graf?
4. Zaproponuj działające wolniejsze rozwiązanie – lepiej skończyć O(n²) niż nie skończyć O(n).

Jak ćwiczyć: 2–3 zadania tygodniowo na głos z zegarem (LeetCode, Codewars – poziom easy/medium), najlepiej z kolegą albo nagrywając się. Na rozmowie mów językiem wzorców: „to klasyczne sliding window, każdy element wchodzi i wychodzi raz, więc O(n) czasu i O(k) pamięci”. Niuans seniorski: wspomnij o czytelności i testowalności kodu (wydzielenie metody, nazwy), a w zadaniach praktycznych – o walidacji wejścia, obsłudze błędów i o tym, jak rozwiązanie zachowa się przy dużym ruchu.

